typedef struct { const Item *base; size_t idx, len; } ItemIter;

void item_iter_init(ItemIter *it, const Inventory *inv) {
    it->base = inv->items; it->idx = 0; it->len = inv->len;
}
bool item_iter_next(ItemIter *it, const Item **out) {
    if (it->idx >= it->len) return false;   /* exhausted */
    *out = &it->base[it->idx++];
    return true;
}
